// GET carries the parameters in the query string, the confirmation form POSTs them as body fields.
const submitted = Object.keys($json.body ?? {}).length > 0;
const p = submitted ? $json.body : ($json.query ?? {});
const id = Number(p.id);
return { json: {
  id: Number.isInteger(id) && id > 0 ? id : 0,
  token: String(p.token ?? ''),
  decision: ['approve', 'reject'].includes(p.decision) ? p.decision : '',
  submitted,
} };

const crypto = require('crypto');
const link = $('Read Link Parameters').item.json;
const row = $json;
let problem = null;
if (!row.id) problem = 'unknown review item';
else if (!link.decision) problem = 'invalid decision';
else if (row.status !== 'pending' || !row.approval_token_hash) problem = 'already decided (' + row.status + ')';
else {
  const given = crypto.createHash('sha256').update(link.token).digest();
  const stored = Buffer.from(row.approval_token_hash, 'hex');
  if (stored.length !== given.length || !crypto.timingSafeEqual(given, stored)) problem = 'invalid token';
}
return { json: { valid: !problem, problem, item: row.id ? { id: row.id, type: row.item_type, itemId: row.item_id, reason: row.reason } : null } };

const page = (title, body, color = '#1f6feb') => '<!doctype html><html lang="de"><head><meta charset="utf-8">' +
  '<meta name="viewport" content="width=device-width,initial-scale=1"><title>' + title + '</title>' +
  '<style>body{font-family:system-ui,sans-serif;max-width:560px;margin:48px auto;padding:0 16px;color:#222}' +
  'h1{font-size:22px;color:' + color + '}button{font-size:16px;padding:10px 18px;border:0;border-radius:6px;' +
  'background:' + color + ';color:#fff;cursor:pointer}.muted{color:#666;font-size:14px}</style></head><body>' +
  '<h1>' + title + '</h1>' + body + '<p class="muted">Muster GmbH · n8n review queue</p></body></html>';
const esc = (s) => String(s ?? '').replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));

const why = $json.problem ?? 'unknown';
return { json: { html: page('Link ungültig / Link not valid',
  '<p>Dieser Link ist ungültig oder wurde bereits verwendet.<br>This link is invalid or has already been used.</p>' +
  '<p class="muted">Reason: ' + esc(why) + '</p>', '#b42318') } };

