const esc = (s) => String(s ?? '').replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));

const link = $('Read Link Parameters').item.json;
const item = $json.item;
const approve = link.decision === 'approve';
const what = {
  document: approve ? 'Freigeben: Entwurfsrechnung in Odoo anlegen / Approve: create a draft vendor bill in Odoo'
                    : 'Ablehnen: Beleg wird nicht gebucht / Reject: the document will not be booked',
  support_request: approve ? 'Als erledigt markieren / Mark as resolved' : 'Verwerfen / Dismiss',
  sync_mismatch: approve ? 'Als erledigt markieren / Mark as resolved' : 'Verwerfen / Dismiss',
}[item.type] ?? link.decision;
const hidden = (n, v) => '<input type="hidden" name="' + n + '" value="' + esc(v) + '">';
return { json: { html: page('Review #' + item.id + ' – ' + (approve ? 'Approve' : 'Reject'),
  '<p><b>' + esc(item.type) + (item.itemId ? ' #' + item.itemId : '') + '</b></p>' +
  '<p>' + esc(item.reason) + '</p>' +
  '<p>' + esc(what) + '</p>' +
  '<form method="post">' + hidden('id', item.id) + hidden('token', link.token) + hidden('decision', link.decision) +
  '<button type="submit">' + (approve ? 'Bestätigen / Confirm' : 'Ablehnen bestätigen / Confirm rejection') + '</button></form>',
  approve ? '#1a7f37' : '#b42318') } };

